def apply(pr,warn):
    n=0
    for sk in('R','L'):
        for p in pr.get(sk,[]):
            for i,q in enumerate(p.get('q',[])):
                k='%s#%d'%(p.get('id'),i)
                if k in FIX:
                    a,o=FIX[k]
                    if len(o)!=len(q['o']):warn.append('opt_fix '+k+': şık sayısı')
                    q['a']=a;q['o']=list(o);n+=1
    return n
